const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));const dialog=document.querySelector('dialog'),form=dialog.querySelector('form'),success=dialog.querySelector('.success');let selectedPlan='Gratuito';document.querySelectorAll('[data-plan]').forEach(b=>b.addEventListener('click',()=>{selectedPlan=b.dataset.plan;document.querySelector('#plan-label').textContent='Plan '+selectedPlan;form.hidden=false;success.hidden=true;dialog.showModal()}));dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});form.addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));try{localStorage.setItem('emprendecopilot-demo',JSON.stringify({...data,plan:selectedPlan}));success.textContent='¡Listo, '+data.name+'! Guardamos la demo de '+data.business+' en este navegador. Tu plan seleccionado es '+selectedPlan+'.'}catch{success.textContent='La demo está lista, pero el navegador no permitió guardarla.'}form.hidden=true;success.hidden=false;const a=document.createElement('a');a.className='btn';a.style.marginTop='18px';a.textContent='Ingresar a mi plataforma →';a.href='platform.html';success.append(document.createElement('br'),a)});
